package net.minecraft.world.level.levelgen;
import java.lang.management.ManagementFactory;
import java.util.*;
/** Real public operations and exact next-source words; bounded intermediate screen. */
public final class SourceScreen {
 static volatile Object retained;static volatile long sink;
 static long gc(){return ManagementFactory.getGarbageCollectorMXBeans().stream().mapToLong(b->Math.max(0,b.getCollectionCount())).sum();}
 static long[] stats()throws Exception{try{var c=Class.forName("net.minecraft.world.level.levelgen.NativeRandomBits");var method=c.getDeclaredMethod("statistics");method.setAccessible(true);return(long[])method.invoke(null);}catch(ClassNotFoundException absent){return new long[0];}}
 static long[] sourceStats()throws Exception{try{var c=Class.forName("net.minecraft.world.level.levelgen.NativeXoroshiroSource");var method=c.getDeclaredMethod("statistics");method.setAccessible(true);return(long[])method.invoke(null);}catch(ClassNotFoundException absent){return new long[0];}}
 static void settle()throws Exception{retained=null;for(int i=0;i<3;i++){System.gc();Thread.sleep(10);}}
 static long work(int kind,XoroshiroRandomSource[] sources){long sum=0;for(int i=0;i<sources.length;i++){var source=sources[i];switch(kind){case 0:for(int j=0;j<32;j++)sum+=source.nextInt(1073741825);break;case 1:for(int j=0;j<32;j++){sum+=Double.doubleToRawLongBits(source.nextDouble());sum^=Float.floatToRawIntBits(source.nextFloat());}break;case 2:source.consumeCount(17);break;case 3:source.setSeed(8765432L+i);break;}sum^=source.nextLong();}retained=sources;sink=sum;return sum;}
 public static void main(String[]args)throws Exception{
  boolean smoke=Arrays.asList(args).contains("--smoke");int only=-1;for(String arg:args)if(arg.startsWith("--kind="))only=Integer.parseInt(arg.substring(7));int target=smoke?1:6,warmup=smoke?2:24;
  for(Class<?> type:new Class<?>[]{Xoroshiro128PlusPlus.class,XoroshiroRandomSource.class}){var url=type.getResource(type.getSimpleName()+".class");try(var input=url.openStream()){System.out.println("SOURCE_ORIGIN "+type.getName()+" "+url+" "+HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(input.readAllBytes())));}}
  var thread=(com.sun.management.ThreadMXBean)ManagementFactory.getThreadMXBean();var compiler=ManagementFactory.getCompilationMXBean();long tid=Thread.currentThread().threadId();
  for(int kind=0;kind<4;kind++){if(only>=0&&kind!=only)continue;settle();long[] initial=stats(),initialSource=sourceStats();int count=smoke?32:(kind<2?32768:262144),accepted=0;
   for(int batch=0;batch<90&&accepted<target;batch++){settle();for(int retry=0;retry<100;retry++){long[] value=stats();long[] source=sourceStats();if((value.length==0||value[0]<=initial[0])&&(source.length==0||source[0]<=initialSource[0]))break;if(retry==99)throw new AssertionError("previous native source owners still live before batch");settle();}var sources=new XoroshiroRandomSource[count];for(int i=0;i<count;i++)sources[i]=new XoroshiroRandomSource(1234567L+i);long[] before=stats(),sourceBefore=sourceStats();long jit=compiler.getTotalCompilationTime(),collections=gc(),allocated=thread.getThreadAllocatedBytes(tid),cpu=thread.getCurrentThreadCpuTime(),start=System.nanoTime();long sum=work(kind,sources);long elapsed=System.nanoTime()-start;cpu=thread.getCurrentThreadCpuTime()-cpu;allocated=thread.getThreadAllocatedBytes(tid)-allocated;long jitDelta=compiler.getTotalCompilationTime()-jit,gcDelta=gc()-collections;long[] after=stats(),sourceAfter=sourceStats();if(sourceAfter.length!=0&&sourceAfter[1]!=sourceBefore[1])throw new AssertionError("source owner recreated during operation");if(after.length!=0&&after[1]-before[1]!=(sourceAfter.length==0&&kind==3?count:0))throw new AssertionError("actual source creation work differs");boolean quiet=batch>=warmup&&jitDelta==0&&gcDelta==0;if(quiet)accepted++;System.out.println("PRODUCER_SCREEN {\"kind\":"+kind+",\"batch\":"+batch+",\"accepted\":"+quiet+",\"count\":"+count+",\"elapsed_ns\":"+elapsed+",\"cpu_ns\":"+cpu+",\"java_bytes\":"+allocated+",\"jit_ms\":"+jitDelta+",\"gc\":"+gcDelta+",\"sum\":"+sum+"}");}
   if(accepted!=target)throw new AssertionError("insufficient quiet samples");settle();for(int retry=0;retry<100;retry++){long[] value=stats();long[] source=sourceStats();if((value.length==0||value[0]<=initial[0])&&(source.length==0||source[0]<=initialSource[0]))break;if(retry==99)throw new AssertionError("actual RNG owners retained after row");settle();}System.out.println("PRODUCER_RETIREMENT "+kind+" random="+Arrays.toString(stats())+" source="+Arrays.toString(sourceStats()));
  }Thread.sleep(250);
 }
}
